head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[localStorage > M > clear]<br/>localStorage 에 저장된 모든 데이터를 삭제합니다.",
    "validation" : [
        "clear() 호출 시 localStorage 에 저장된 모든 데이터가 삭제되어야 합니다.",
        "clear() 호출 후 getItem() 으로 조회하면 null 이 반환되어야 합니다.",
        "WebSquare.localStorage 를 통해 저장한 데이터뿐 아니라 네이티브 localStorage 에 저장된 모든 데이터가 삭제되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 기존 데이터 초기화
    WebSquare.localStorage.clear();
};



scwin.btn_setTestData_onclick = function () {
    // WebSquare localStorage 로 저장
    WebSquare.localStorage.setItem("clearTest1", "aaa");
    WebSquare.localStorage.setItem("clearTest2", "bbb");

    // 네이티브 localStorage 로 저장
    window.localStorage.setItem("nativeTest1", "ccc");

    var allData = WebSquare.localStorage.getAllItem();
    var keyCount = Object.keys(allData).length;
    var nativeCount = window.localStorage.length;

    // WebSquare getItem 으로 개별 키 삭제 확인
    var wsTest1 = WebSquare.localStorage.getItem("clearTest1");
    var wsTest2 = WebSquare.localStorage.getItem("clearTest2");
    var nativeTest = window.localStorage.getItem("nativeTest1");   

    wf_body_bottom.getObj("scwin").setReturnValue("getItem('clearTest1') : " + wsTest1);
    wf_body_bottom.getObj("scwin").setReturnValue("getItem('clearTest2') : " + wsTest2);
    wf_body_bottom.getObj("scwin").setReturnValue("네이티브 getItem('nativeTest1') : " + nativeTest);     
    wf_body_bottom.getObj("scwin").setReturnValue("테스트 데이터 저장 완료");
}



scwin.btn_clear_onclick = function () {
    // clear 호출
    WebSquare.localStorage.clear();

    // 네이티브 localStorage 기준으로 삭제 확인
    var nativeCount = window.localStorage.length;

    // WebSquare getItem 으로 개별 키 삭제 확인
    var wsTest1 = WebSquare.localStorage.getItem("clearTest1");
    var wsTest2 = WebSquare.localStorage.getItem("clearTest2");
    var nativeTest = window.localStorage.getItem("nativeTest1");

    wf_body_bottom.getObj("scwin").setReturnValue("clear() 호출 완료");
    wf_body_bottom.getObj("scwin").setReturnValue("getItem('clearTest1') : " + wsTest1);
    wf_body_bottom.getObj("scwin").setReturnValue("getItem('clearTest2') : " + wsTest2);
    wf_body_bottom.getObj("scwin").setReturnValue("네이티브 getItem('nativeTest1') : " + nativeTest);
    wf_body_bottom.getObj("scwin").setReturnValue("전체 삭제 확인 : " + (nativeCount === 0 && wsTest1 === null && wsTest2 === null ? "PASS" : "FAIL"));
}
